+/** Compares sold recipe portions with ledger consumption over inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const inRange = (at) => {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  const actual = new Map();
+  const add = (totals, itemId, qty) => totals.set(itemId, (totals.get(itemId) ?? 0) + Math.round(qty * 1000));
+  for (const sale of store.data.sales) {
+    if (inRange(sale.soldAt))
+      for (const ingredient of sale.ingredients) add(theoretical, ingredient.itemId, ingredient.qty);
+  }
+  const itemsByBatch = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type === "consume" && inRange(movement.at))
+      add(actual, itemsByBatch.get(movement.batchId), movement.qty);
+  }
+  return listItems(store).flatMap(({ id: itemId }) => {
+    const used = actual.get(itemId) ?? 0;
+    const expected = theoretical.get(itemId) ?? 0;
+    return used || expected
+      ? [{ itemId, theoretical: expected / 1000, actual: used / 1000, variance: (used - expected) / 1000 }]
+      : [];
+  });
+}
