diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..98c275d
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,60 @@
+import { memoryStore } from "../db/store.js";
+import { isDate } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})$/i;
+const field = '(?:"(?:[^"]|"")*"|[^",]*)';
+const csvLine = new RegExp(`^${field}(?:,${field})*$`);
+
+function invalid(row, reason) {
+  throw new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Imports sale lines atomically, counting new tickets and portions sold. */
+export function importSales(store, csv) {
+  if (typeof csv !== "string") invalid(1, "csv is required");
+  const [header, ...lines] = csv.split(/\r?\n/);
+  const keys = (parseCsv(header)[0] ?? []).map((key) => key.trim());
+  if (!csvLine.test(header) || keys.length !== columns.length || !columns.every((key) => keys.includes(key)))
+    invalid(1, "expected ticket,soldAt,dishId,qty");
+
+  const staged = memoryStore(store.data);
+  const existing = new Set(store.data.sales.map((sale) => sale.ticket));
+  const imported = new Set();
+  let dishes = 0;
+  for (const [index, line] of lines.entries()) {
+    if (!line.trim()) continue;
+    const row = index + 2;
+    const [fields] = parseCsv(line);
+    if (!csvLine.test(line) || fields.length !== keys.length) invalid(row, "invalid CSV fields");
+    const [ticket, soldAt, dish, quantity] = columns.map((key) => fields[keys.indexOf(key)].trim());
+    const dishId = Number(dish);
+    const qty = Number(quantity);
+    if (!ticket) invalid(row, "missing ticket");
+    if (!instant.test(soldAt) || !isDate(soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(soldAt)))
+      invalid(row, "invalid soldAt");
+    if (!/^\d+$/.test(quantity) || !Number.isSafeInteger(qty) || qty < 1) invalid(row, "invalid qty");
+    if (!/^\d+$/.test(dish) || !Number.isSafeInteger(dishId) || dishId < 1) invalid(row, "invalid dishId");
+    try {
+      const recipe = getRecipe(staged, getDish(staged, dishId).recipeId);
+      if (existing.has(ticket)) continue;
+      const ingredients = scaled(recipe, qty);
+      for (const need of ingredients) {
+        if (need.qty > 0) consume(staged, need.itemId, need.qty, { at: soldAt, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ ticket, soldAt, dishId, qty, ingredients });
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      invalid(row, error.code === "not_found" ? "unknown dish or recipe" : error.code.replaceAll("_", " "));
+    }
+    imported.add(ticket);
+    dishes += qty;
+  }
+  store.data = staged.data;
+  return { tickets: imported.size, dishes };
+}
